import{_ as s,o as e,c as p,a3 as r}from"./chunks/framework.BwzYn71E.js";const h=JSON.parse('{"title":"1.1 那我问你，什么是阻塞控制","description":"","frontmatter":{"translationSource":{"title":"1.1 那我问你，什么是阻塞控制","archivedAt":"2026-11-23","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=quUTb9JSv879txqKEKI0BS","scope":"page"},"translationLang":"zh","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/zh/1-1-so-tell-me-what-is-production-controlled-by-blocking"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/1-1-so-tell-me-what-is-production-controlled-by-blocking"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/1-1-so-tell-me-what-is-production-controlled-by-blocking"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/1-1-so-tell-me-what-is-production-controlled-by-blocking"}]]},"headers":[],"relativePath":"zh/1-1-so-tell-me-what-is-production-controlled-by-blocking.md","filePath":"zh/page-quUTb9JSv879txqKEKI0BS.md"}'),n={name:"zh/1-1-so-tell-me-what-is-production-controlled-by-blocking.md"};function o(l,a,t,i,c,d){return e(),p("div",null,[...a[0]||(a[0]=[r('<div class="logistics-content"><h1 id="_1-1-那我问你-什么是阻塞控制" tabindex="-1">1.1 那我问你，什么是阻塞控制 <a class="header-anchor" href="#_1-1-那我问你-什么是阻塞控制" aria-label="Permalink to &quot;1\\.1 那我问你，什么是阻塞控制&quot;">​</a></h1><p class="page-updated" data-update-status="recorded"><span>本页内容更新：</span><a href="/endfield-skydoc/zh/changelog/capture-2026-11-23T06-44-45-722Z-4358a738" title="网站最近同步到本页内容变更的时间（北京时间），不代表源作者实际编辑时间。点击查看更新记录。" aria-label="本页内容更新：2026-11-23. 网站最近同步到本页内容变更的时间（北京时间），不代表源作者实际编辑时间。点击查看更新记录。"><time datetime="2026-11-23T06:44:47.018Z">2026-11-23</time></a><span class="page-updated-zone">（北京时间）</span></p><blockquote><p>源页面 ID：<code>quUTb9JSv879txqKEKI0BS</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=quUTb9JSv879txqKEKI0BS" target="_blank" rel="noreferrer">在腾讯文档中打开</a></p></blockquote><p>本页最后更新：26-11-16</p><p><span id="source-block-cOjAkmc10z8olELAj3s3mC"></span></p><h2 id="我们需要智能控制" tabindex="-1">我们需要智能控制！ <a class="header-anchor" href="#我们需要智能控制" aria-label="Permalink to &quot;我们需要智能控制！&quot;">​</a></h2><p><span id="source-block-OSs33Rg87xrRr23FlHyMo0"></span></p><h3 id="无处不在的控制" tabindex="-1">无处不在的控制 <a class="header-anchor" href="#无处不在的控制" aria-label="Permalink to &quot;无处不在的控制&quot;">​</a></h3><p>从这里开始，我们可能要换换脑子，从<strong>控制</strong>的角度来看待终末地的产线。</p><p>什么是<strong>控制</strong>？一般理解，<strong>控制</strong>就是我们对产线做了某些操作，使得生产情况发生了一些变化。比方说，你把一个正在从源矿生产晶体外壳的精炼炉关掉，晶体外壳产量就少了每分钟30，源矿消耗量也少了每分钟30。为了消耗掉这些源矿，你又把这一路源矿拉了一条传送带送去粉碎机做成源石粉末。这就是对产线的一种<strong>控制</strong>。</p><p>广义上说，只要你打开产线干点儿什么，薅点儿零件做炮塔，把机器搬来搬去，或者在野外插两个矿机水泵，都可以算作<strong>控制</strong>，只不过，有时候这些<strong>控制</strong>起不到什么效果。很多时候我们只关心那些<u>能达到我们想要的生产规划的控制</u>，所以可能时不时就看到有人说什么息壤气忘了关或者铜块爆仓了，得上号调产线。</p><p>但是，一来人总是懒的，二来我们也不可能一直花精力去调产线，所以我们就会想要让别的东西<s>三字母</s>代替我们来<strong>控制</strong>产线。由此，<span class="mark-blue"><strong>智能控制</strong></span>应运而生。它指的是我<u>们事先设置好某种</u><u><strong>条件</strong></u><u>，或者称之为</u><u><strong>触发器</strong></u><u>，然后我们无需亲自干预，在满足相应设定条件的情况下，产线自动地形成某种调整，从而达到我们所希望的生产目的</u>。</p><hr><p><span id="source-block-Lx2bUyoi8CJRjyEcr0q8fI"></span></p><h3 id="两种智能控制" tabindex="-1">两种智能控制 <a class="header-anchor" href="#两种智能控制" aria-label="Permalink to &quot;两种智能控制&quot;">​</a></h3><p>由于终末地工业缺少智能化的原件（例如判断库存达到某个值时，控制阀门打开），我们要从什么角度来设置<strong>控制的触发条件</strong>呢？目前应用较为广泛的可能仅有<span class="mark-red"><strong>时钟信号、阻塞信号</strong></span>。</p><p><span id="source-block-Z6mdADAvF3e1OBMkc4MQyH"></span></p><h4 id="时钟信号控制" tabindex="-1">时钟信号控制 <a class="header-anchor" href="#时钟信号控制" aria-label="Permalink to &quot;时钟信号控制&quot;">​</a></h4><p><strong>时钟信号控制</strong>基于如下朴素的思想：<u>我们设一个定时器，时间到了就干点儿什么</u>。</p><p>基于此，<strong>时钟信号控制主要</strong>关心两个方面：如何设计想要的定时器和时钟信号，以及如何让定时器触发时控制其他产线。</p><p>一些时钟信号控制的例子：</p><ul><li><p>本人曾使用时钟信号实现单烘炉重息壤生产<a href="/endfield-skydoc/zh/single-forge-heavy-xiranite-using-clock-signals">基于时钟信号的单烘炉重息壤方案</a></p></li><li><p>本页面下半部分的信号控制</p></li><li><p>II型销毁初号机<a href="/endfield-skydoc/zh/optimizing-the-reactor-crucible-trash-can">优化反应池垃圾桶</a>，<a href="/endfield-skydoc/zh/producing-xircon-effluent-in-a-single-reactor-crucible">单个反应池生产壤晶废液</a></p></li></ul><p>本教程一般不探讨<span class="mark-red"><strong>时钟信号</strong></span>的应用。</p><p><span id="source-block-bZK26YZ76HqQdceorQf5y1"></span></p><h4 id="阻塞信号控制" tabindex="-1">阻塞信号控制 <a class="header-anchor" href="#阻塞信号控制" aria-label="Permalink to &quot;阻塞信号控制&quot;">​</a></h4><p><strong>阻塞信号控制</strong>基于如下朴素的思想：<u>一个地方堵塞了，就会一直往上游堵，多余的材料会溢流到别的地方去</u>。</p><p>基于此，<strong>阻塞信号控制同样</strong>关心两个方面：应该考虑什么地方的堵塞，以及如何让这种堵塞信号控制其他产线。</p><p>本教程主要探讨<span class="mark-red"><strong>阻塞信号</strong></span>的应用。</p><p><span id="source-block-qxxUQgNM3ODcztb9dyEMbo"></span></p><h2 id="有哪些优秀的阻塞信号与控制方法" tabindex="-1">有哪些优秀的阻塞信号与控制方法？ <a class="header-anchor" href="#有哪些优秀的阻塞信号与控制方法" aria-label="Permalink to &quot;有哪些优秀的阻塞信号与控制方法？&quot;">​</a></h2><p><span id="source-block-k8JUYPUhl574wPiEOg449E"></span></p><h3 id="例子" tabindex="-1">例子 <a class="header-anchor" href="#例子" aria-label="Permalink to &quot;例子&quot;">​</a></h3><p>当然，这毕竟只是节引言，所以只是简单看几个例子。我们可以根据多种具有实际生产意义的信号，提炼出其中带有阻塞信号的部分，并自然地用溢流方式进行控制，从而在生产中带来多方面的便利。例如：</p><p><span class="mark-purple">Q：我想先生产</span><span class="mark-purple"><u>一仓库的紫晶瓶</u></span><span class="mark-purple">，然后再开始生产</span><span class="mark-purple"><u>高晶瓶</u></span><span class="mark-purple">。</span></p><p><span class="mark-red">A：紫晶瓶仓储已满 → 塑形机的输出缓存阻塞，连带着输入缓存也阻塞，多余紫晶矿溢流生产高晶瓶。</span></p><p><span class="mark-purple">Q：我想</span><span class="mark-purple"><u>保证仓库内一直有钢零件随用随取</u></span><span class="mark-purple">，在不用时也不浪费钢的产能，都去做谷地电池。</span></p><p><span class="mark-red">A：同上</span></p><p><span class="mark-purple">Q：我想让赤铜块</span><span class="mark-purple"><u>先做赤铜零件</u></span><span class="mark-purple">，为了防止铜块爆仓堵住污水，赤铜零件做满后需要</span><span class="mark-purple"><u>让赤铜块继续做赤铜装备元件</u></span><span class="mark-purple">。</span></p><p><span class="mark-red">A：赤铜零件库存满 → 赤铜零件回仓阻塞，溢流到赤铜装备元件机，防止污水不足。</span></p><p><span class="mark-purple">Q：我想让息壤</span><span class="mark-purple"><u>优先满足中容武陵电池</u></span><span class="mark-purple">的生产需求，多余的息壤再做别的，这样即使我偶尔从谷地搬运多余的致密源石粉末到武陵，也能够消耗掉。</span></p><p><span class="mark-red">A：液化息壤优先供应壤晶生产，然后再用于重息壤生产 → 壤晶生产端液化息壤阻塞，致密源石粉末有多少全用掉，其数量决定壤晶、电池的产量和液化息壤消耗量，同时间接控制重息壤生产量。</span></p><p><span class="mark-purple">Q：我不想让转化机白吃息壤，我需要它有多少原料给多少息壤</span></p><p><span class="mark-red">A：液气机反馈中，仅当原料液体充足时，才供应液化息壤 → 原料液体堆积时，阻塞液化息壤的循环回路，让液化息壤溢流进入液气机供给路线。</span></p><p><span class="mark-purple">Q：我想</span><span class="mark-purple"><u>把原材料全部用完做成成品</u></span><span class="mark-purple">，即使成品产速为一个复杂分数，使用自适应方案也能自动达到这一产速。</span></p><p><span class="mark-red">A：解释起来太复杂，但反正也是本教程会讨论的内容。</span><a href="/endfield-skydoc/zh/3-1-the-beginnings-of-automatic-balancing-xiranite-and-originium-powders">3.1 自动配平思想的萌芽：息壤与源石粉末的爱恨情仇</a></p><p>由此可见，我们可以根据实际的生产需求，有意地构建或利用可能形成阻塞的结构，利用不同阻塞状态下流量产生的变化来达成阻塞控制，智能生产的目的。也可以注意到，阻塞控制天然地和溢流紧密相关，代表了产线流量在不同条件下发生的变化。<strong>阻塞控制原理</strong>所要探讨的内容就包括：<strong>如何构建这些阻塞控制结构，产线流量发生怎样的变化，是否能达成预期的生产目的</strong>。</p><p><span id="source-block-0tbsYIllXAnTdtaVMTs8Be"></span></p><h3 id="杂谈" tabindex="-1">杂谈 <a class="header-anchor" href="#杂谈" aria-label="Permalink to &quot;杂谈&quot;">​</a></h3><blockquote><p>爆仓当然是阻塞的一种表现，所以爆仓时产线会如何发生变化，也是阻塞控制原理所关注的重要内容（爆仓动力学.jpg）</p></blockquote><blockquote><p>关于阻塞控制与阻塞流理论的联系，可参考<a href="/endfield-skydoc/zh/4-0-building-the-science-of-blocking-based-production-on-blocking-flow">4.0 从阻塞流理论基石上建起阻塞生产学的大厦（缓更）</a>一节，以及<a href="/endfield-skydoc/zh/flow-theory-for-idealized-logistics-systems">理想系统的流量理论</a>等相关内容</p></blockquote><blockquote><p>如果说初级的产线设计是达到把一定数目或者速率的原料x<em>供给做成一定速率的产品y</em>（即做完后报表图显示正确），f(x*) = y*, 那么本文所讨论的就是更高一层次的产线设计：在前者基础上，探讨在外部环境（如原料供给，或产物堆满）发生变化的情形下，产线的响应是什么，以及如何应用这些产线的响应达到我们想要的更复杂的生产需求。我们需要分析函数f是否对一定范围内的x都能给出正确的y；产线在原料x<em>的供应量发生变化时，y</em>是否能够正确地反映我们想要的结果；或者在y<em>发生变化时，x</em>能否正确发生相应的响应。</p></blockquote><p>阻塞控制并不是神秘高深的理论，只需要你在原有产线基础上再接着往下多想一步，大家或许已经在各种地方见到过使用过了，相比之下更关键的是如何理解这一现象。接下来我们就从最基本的结构出发，来从阻塞控制的角度重新认识终末地的产线。</p><p><a href="/endfield-skydoc/zh/1-2-what-are-the-benefits-of-blocking-based-production">1.2 基本概念与单路控制结构（单入单出）</a></p><p><a href="/endfield-skydoc/zh/production-control-and-frontier-research">生产控制与前沿研究</a></p></div>',1)])])}const k=s(n,[["render",o]]);export{h as __pageData,k as default};
